1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = QuoteResult | ClaimResult;
41	
42	export interface QuoteResult {
43	  premium: number;
44	}
45	
46	export interface ClaimResult {
47	  payout: number;
48	  remainingCap: number;
49	}
50	
51	export interface ScenarioResult {
52	  results: Result[];
53	}
54	
55	const PROCESSING_FEE = 5;
56	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
57	
58	// What a single item of each type is worth to the MHPCO: what it costs to
59	// insure, and what it is insured for. Keeping the two figures side by side
60	// makes this the one place that says which item types exist at all.
61	interface ItemTypeRates {
62	  basePremium: number;
63	  insuranceValue: number;
64	}
65	
66	const ITEM_TYPE_RATES: Record<string, ItemTypeRates> = {
67	  sword: { basePremium: 100, insuranceValue: 1000 },
68	  amulet: { basePremium: 60, insuranceValue: 600 },
69	  staff: { basePremium: 80, insuranceValue: 800 },
70	  potion: { basePremium: 40, insuranceValue: 400 },
71	  rune: { basePremium: 25, insuranceValue: 250 },
72	  moonstone: { basePremium: 25, insuranceValue: 250 },
73	};
74	
75	const LOYALTY_YEARS_THRESHOLD = 2;
76	const LOYALTY_DISCOUNT_RATE = 2 / 10;
77	const FOLLOW_UP_DISCOUNT_RATE = 15 / 100;
78	const CURSE_SURCHARGE_RATE = 1 / 2;
79	const HIGH_ENCHANTMENT_THRESHOLD = 5;
80	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
81	const BLOCK_SIZE = 3;
82	const BLOCK_BASE_PREMIUM = 60;
83	const DEDUCTIBLE = 100;
84	const CAP_MULTIPLIER = 2;
85	const REDUCED_REIMBURSEMENT_THRESHOLD = 8;
86	const REDUCED_REIMBURSEMENT_RATE = 1 / 2;
87	
88	const unitBasePremium = (type: string): number =>
89	  ITEM_TYPE_RATES[type].basePremium;
90	
91	const countByType = (items: Item[]): Map<string, number> =>
92	  items.reduce(
93	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
94	    new Map<string, number>(),
95	  );
96	
97	// A building block of 3 alike components is offered at a special base premium.
98	const basePremiumForItemGroup = (type: string, count: number): number =>
99	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);
100	
101	const policyBasePremium = (items: Item[]): number =>
102	  [...countByType(items)].reduce(
103	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
104	    0,
105	  );
106	
107	// Premium-side enchantment rule (threshold 5), distinct from the claim-side
108	// reduced-reimbursement rule (threshold 8).
109	const qualifiesForHighEnchantmentSurcharge = (item: Item): boolean =>
110	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
111	
112	const surchargeRate = (item: Item): number =>
113	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
114	  (qualifiesForHighEnchantmentSurcharge(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
115	
116	// Item-specific modifiers apply to the affected item's own base premium, i.e.
117	// the unit price of its type — a block discount never shrinks a surcharge.
118	const itemSurcharge = (item: Item): number =>
119	  unitBasePremium(item.type) * surchargeRate(item);
120	
121	const itemSurcharges = (items: Item[]): number =>
122	  items.reduce((total, item) => total + itemSurcharge(item), 0);
123	
124	const isLongStanding = (customer: Customer): boolean =>
125	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
126	
127	// Policy-wide modifiers apply to the policy base premium only — never to the
128	// item surcharges. Net signed delta: a discount can outweigh the surcharge.
129	// Every quote is a first insurance for its items, regardless of customer
130	// history, so that surcharge always applies.
131	const policyAdjustmentRate = (
132	  customer: Customer,
133	  isFollowUpContract: boolean,
134	): number =>
135	  FIRST_INSURANCE_SURCHARGE_RATE -
136	  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0) -
137	  (isFollowUpContract ? FOLLOW_UP_DISCOUNT_RATE : 0);
138	
139	// Premiums round up, in the MHPCO's favour. The adjustment is added as a
140	// separate term rather than folded into a `base * 1.1` factor, which is not
141	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
142	const quotePremium = (
143	  items: Item[],
144	  customer: Customer,
145	  isFollowUpContract: boolean,
146	): number => {
147	  const base = policyBasePremium(items);
148	  return Math.ceil(
149	    base +
150	      itemSurcharges(items) +
151	      base * policyAdjustmentRate(customer, isFollowUpContract) +
152	      PROCESSING_FEE,
153	  );
154	};
155	
156	const unitInsuranceValue = (type: string): number =>
157	  ITEM_TYPE_RATES[type].insuranceValue;
158	
159	// The total payout per policy is capped at twice the insurance sum. Premium
160	// modifiers never reach the insurance sum: it is the plain sum of the unit
161	// values of the insured items.
162	const insuranceSum = (items: Item[]): number =>
163	  items.reduce((sum, item) => sum + unitInsuranceValue(item.type), 0);
164	
165	// A policy created by a quote step, tracked so later claims can pay out
166	// against it. `remainingCap` shrinks as successive claims are settled.
167	interface Policy {
168	  items: Item[];
169	  remainingCap: number;
170	}
171	
172	const openPolicy = (items: Item[]): Policy => ({
173	  items,
174	  remainingCap: CAP_MULTIPLIER * insuranceSum(items),
175	});
176	
177	// State accumulated by the steps run so far. Later steps price and pay out
178	// against what earlier steps established, so each step reads the state it was
179	// run with and returns the state the next step should see.
180	interface ScenarioState {
181	  customer: Customer;
182	  contractsSoFar: number;
183	  // Keyed by the zero-based index of the quote step that created the policy.
184	  policies: Map<number, Policy>;
185	}
186	
187	// A step's outcome: what to report, and how the scenario stands afterwards.
188	interface StepOutcome {
189	  result: Result;
190	  state: ScenarioState;
191	}
192	
193	// Records a policy against the step index that identifies it, leaving the
194	// state it was given untouched.
195	const withPolicy = (
196	  state: ScenarioState,
197	  policyId: number,
198	  policy: Policy,
199	): ScenarioState => ({
200	  ...state,
201	  policies: new Map(state.policies).set(policyId, policy),
202	});
203	
204	const quote = (
205	  step: QuoteStep,
206	  state: ScenarioState,
207	  stepIndex: number,
208	): StepOutcome => ({
209	  result: {
210	    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
211	  },
212	  state: withPolicy(
213	    { ...state, contractsSoFar: state.contractsSoFar + 1 },
214	    stepIndex,
215	    openPolicy(step.items),
216	  ),
217	});
218	
219	// Claim-side enchantment rule (threshold 8), distinct from the premium-side
220	// high-enchantment surcharge (threshold 5).
221	const qualifiesForReducedReimbursement = (item: Item): boolean =>
222	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_THRESHOLD;
223	
224	// Damage to heavily enchanted items is reimbursed at 50 % of the damage amount.
225	const reimbursementRate = (item: Item): number =>
226	  qualifiesForReducedReimbursement(item) ? REDUCED_REIMBURSEMENT_RATE : 1;
227	
228	// A damage entry together with the specific insured item it was matched to.
229	interface MatchedDamage {
230	  damage: Damage;
231	  item: Item;
232	}
233	
234	// What a single damage entry entitles the claimant to, before the policy-wide
235	// cap is applied. A deductible applies per damage event, i.e. once per damaged
236	// item. Special clauses reduce the reimbursement first; the deductible comes
237	// off after.
238	const damageEntitlement = ({ damage, item }: MatchedDamage): number =>
239	  damage.amount * reimbursementRate(item) - DEDUCTIBLE;
240	
241	// Pairs each damage entry with a distinct insured item of the same type: two
242	// damages to "sword" refer to two different insured swords, not the same one
243	// twice. Instances of a type are consumed in the order they were insured.
244	const matchDamagesToItems = (
245	  insuredItems: Item[],
246	  damages: Damage[],
247	): MatchedDamage[] => {
248	  const unclaimed = [...insuredItems];
249	  return damages.map((damage) => {
250	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
251	    if (index === -1) {
252	      throw new Error(
253	        `the policy does not cover a damaged ${damage.itemType}`,
254	      );
255	    }
256	    return { damage, item: unclaimed.splice(index, 1)[0] };
257	  });
258	};
259	
260	// Reading a policy the scenario never opened is a programming error rather
261	// than a claimant's mistake, so this says so plainly instead of asserting the
262	// lookup succeeded and failing later with an incidental TypeError. Validating
263	// the claim step's policy index against the scenario is a separate concern,
264	// still to be specified.
265	const policyFor = (state: ScenarioState, policyId: number): Policy => {
266	  const policy = state.policies.get(policyId);
267	  if (policy === undefined) {
268	    throw new Error(`there is no policy ${policyId}`);
269	  }
270	  return policy;
271	};
272	
273	// The MHPCO does not reimburse a negative loss.
274	const rejectNegativeAmounts = (damages: Damage[]): void => {
275	  const negative = damages.find((damage) => damage.amount < 0);
276	  if (negative !== undefined) {
277	    throw new Error(
278	      `damage amount ${negative.amount} for ${negative.itemType} is negative`,
279	    );
280	  }
281	};
282	
283	const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
284	  const policy = policyFor(state, step.policy);
285	  rejectNegativeAmounts(step.incident.damages);
286	  const matchedDamages = matchDamagesToItems(policy.items, step.incident.damages);
287	  const desiredPayout = matchedDamages.reduce(
288	    (total, matched) => total + damageEntitlement(matched),
289	    0,
290	  );
291	  // The total payout per policy is capped; a claim gets at most what is left.
292	  const payout = Math.min(desiredPayout, policy.remainingCap);
293	  const remainingCap = policy.remainingCap - payout;
294	  return {
295	    result: { payout, remainingCap },
296	    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
297	  };
298	};
299	
300	const runStep = (
301	  step: Step,
302	  state: ScenarioState,
303	  stepIndex: number,
304	): StepOutcome => {
305	  switch (step.op) {
306	    case "quote":
307	      return quote(step, state, stepIndex);
308	    case "claim":
309	      return claim(step, state);
310	  }
311	};
312	
313	export const runScenario = (scenario: Scenario): ScenarioResult => {
314	  const initialState: ScenarioState = {
315	    customer: scenario.customer,
316	    contractsSoFar: 0,
317	    policies: new Map(),
318	  };
319	  const { results } = scenario.steps.reduce<{
320	    results: Result[];
321	    state: ScenarioState;
322	  }>(
323	    ({ results, state }, step, stepIndex) => {
324	      const outcome = runStep(step, state, stepIndex);
325	      return { results: [...results, outcome.result], state: outcome.state };
326	    },
327	    { results: [], state: initialState },
328	  );
329	  return { results };
330	};
