const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
  const policy = policyFor(state, step.policy);
  rejectNegativeAmounts(step.incident.damages);
  const matchedDamages = matchDamagesToItems(policy.items, step.incident.damages);
  const desiredPayout = matchedDamages.reduce(
    (total, matched) => total + damageEntitlement(matched),
    0,
  );
  // The total payout per policy is capped; a claim gets at most what is left.
  const payout = Math.min(desiredPayout, policy.remainingCap);
  const remainingCap = policy.remainingCap - payout;
  return {
    result: { payout, remainingCap },
    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
  };
};

